    "hook": "녹읍은 신라, 전시과는 고려, 과전법은 고려 끝(공양왕 때), 직전법은 조선(세조 때)입니다. 직전법은 과전법의 수신전과 휼양전을 없앤 것이므로 과전법 다음입니다.",
