      "② 보도 지침으로 언론이 통제되었다: 전두환 정부 때의 일이므로 정답입니다. 정부가 언론사에 기사의 크기와 방향까지 지시했고, 이 사실이 잡지 말을 통해 세상에 알려졌습니다(1986년).",
