      "④ 관청에 필요한 물품을 납품하는 공인: 조선 후기의 모습입니다. 대동법(광해군 때 경기도에서 시작, 숙종 때 전국으로 확대)이 시행되면서 나라에 물건을 대는 상인인 공인이 나타났습니다.",
      "⑤ 송파장에서 산대놀이 공연을 벌이는 광대: 조선 후기의 모습입니다. 장시가 전국에 퍼졌고 송파장 같은 큰 장에서 탈놀이가 벌어졌습니다."
