    "reason": "조선 태형령(1912년)은 조선 사람에게만 매를 때리는 벌을 줄 수 있게 한 법으로, 헌병 경찰이 재판 없이 벌을 주는 즉결 처분과 함께 무단 통치(1910년대)를 떠받쳤습니다. 3.1 운동(1919년) 뒤 통치 방식을 바꾸면서 없앴습니다(1920년). 그러니 1910년대의 일을 찾으면 됩니다. 조선 총독부는 식민 통치 5년의 성과를 자랑하려고 경복궁의 전각을 헐고 조선 물산 공진회(1915년)를 열었습니다. 따라서 ⑤입니다.",
