    "hook": "공물을 쌀로 바꾼 대동법(광해군 때)에는 선혜청과 공인이 붙습니다. 군포를 줄인 균역법(영조 때)에는 결작, 어장세와 선박세, 선무군관포가 붙습니다. 결작도 토지에 매기는 것이라 대동법과 섞이기 쉽습니다.",
