    "hook": "덕수궁(경운궁)은 고종이 러시아 공사관에서 돌아온 곳이고, 석조전과 중명전과 돈덕전이 있으며, 석조전에서 미소 공동 위원회가 열렸습니다. 서궐은 경희궁, 창경원은 창경궁, 정도전이 이름 지은 곳은 경복궁, 태종이 지은 곳은 창덕궁입니다.",
