    "hook": "철도가 열린 차례는 경인선(대한 제국 때, 1899년) → 경부선(대한 제국 때, 1905년) → 경의선(대한 제국 때, 1906년)입니다. 경인선이 열릴 때는 한성 사범 학교와 소학교가 이미 있었고, 근우회와 학도 지원병은 일제 강점기의 일입니다.",
