    "reason": "네 모둠의 주제가 모두 충주에 있습니다. 탑평리 칠층 석탑은 나라 한가운데쯤에 있다고 해서 중앙탑이라고도 부르는 통일 신라의 탑입니다. 김윤후는 처인성 싸움(고려 고종 때)에 이어 충주성에서 노비 문서를 불태우며 백성과 함께 몽골군을 막았습니다(고려 고종 때). 다인철소 사람들도 몽골군과 싸워 그 공으로 소에서 현으로 올라갔습니다(고려 고종 때). 신립은 임진왜란(선조 때) 때 충주 탄금대에서 강을 등지고 싸우다 졌습니다. 충주에는 고구려가 한강 유역까지 내려온 것을 보여 주는 충주 고구려비가 있는데, 남한에서 찾은 고구려 비석은 이것 하나뿐입니다. 따라서 ④입니다.",
    "choices": [
      "① 제1차 미소 공동 위원회 개최: 서울 덕수궁 석조전에서 열렸습니다(미군정기, 1946년). 임시 정부를 세울 때 어느 단체와 협의할지를 놓고 미국과 소련이 맞서 깨졌습니다.",
      "② 명 신종을 기리는 만동묘 건립: 충청북도 괴산 화양동입니다(숙종 때). 송시열의 뜻에 따라 그 제자들이 세웠고, 흥선 대원군 집권기(고종 때)에 철폐되었습니다. 충주와 같은 충청북도라 헷갈리기 쉽습니다.",
      "③ 강주룡의 을밀대 지붕 농성: 평양입니다(1930년대 초). 평원 고무 공장 노동자가 임금 삭감에 맞서 높은 곳에 올라가 버텼습니다.",
      "④ 남한에서 하나뿐인 고구려비 발견: 충주 고구려비입니다. 고구려가 남쪽으로 세력을 넓힌 것(장수왕 때)을 보여 주는 비석이므로 정답입니다.",
      "⑤ 박재혁의 경찰서 폭탄 의거: 부산입니다(1920년). 의열단원 박재혁이 부산 경찰서장에게 폭탄을 던졌습니다."
    ],
    "hook": "탄금대, 중앙탑, 김윤후의 충주성, 다인철소가 보이면 충주입니다. 충주에서 고를 것은 고구려비 하나입니다. 김윤후는 처인성(용인)과 충주성 두 곳에서 몽골을 막았습니다.",
