    "reason": "독립문을 세운 단체는 독립 협회(고종 때, 1896년 창립)입니다. 서재필이 중심이 되어 독립신문을 내고 영은문 자리에 독립문을 세웠습니다. 대한 제국 수립 뒤에는 만민 공동회와 관민 공동회(고종 때, 대한 제국)를 열어 이권을 넘기는 데 반대하고 헌의 6조를 올렸습니다. 이어 중추원을 고쳐 의원의 절반을 독립 협회가 뽑는 의회를 만들려 했습니다. 정부가 중추원 관제를 고쳐 반포하기까지 했지만, 보수 세력의 모함으로 독립 협회는 해산되었습니다(고종 때, 1898년). 따라서 ④입니다.",
