    "reason": "헤이그 특사 파견(고종 때, 1907년)을 구실로 일제는 고종을 물러나게 하고 순종을 세웠습니다. 문제는 이 일 뒤를 묻습니다. 그 뒤로 한일 신협약과 군대 해산(순종 때, 1907년) → 기유각서로 사법권을 빼앗김(순종 때, 1909년) → 경찰권을 빼앗김(순종 때, 1910년) → 국권 피탈(1910년)이 이어졌습니다. 따라서 ④입니다.",
