    "hook": "영조에게 붙는 것은 연잉군, 탕평 교서와 탕평비, 균역법, 청계천 준설과 준천사, 신문고 다시 설치, 속대전입니다. 정조는 장용영, 규장각, 초계문신제, 수원 화성, 대전통편이고, 고종 때 흥선 대원군은 대전회통입니다.",
