    "hook": "조선 관청은 하는 일로 가릅니다. 의정부는 세 정승의 회의, 승정원(은대)은 왕명 출납과 승정원일기, 의금부는 큰 죄인, 사헌부와 사간원과 홍문관은 삼사, 한성부는 서울, 춘추관은 역사 기록, 비변사는 처음엔 국방 회의 기구입니다.",
    "reviewedOn": "2026-10-14"
