    "hook": "예송은 현종 때 두 번입니다. 효종이 죽었을 때가 기해예송(서인이 이김, 1년 복), 효종비가 죽었을 때가 갑인예송(남인이 이김)입니다. 송준길과 송시열은 서인, 허목과 윤휴는 남인입니다. 뒤이어 숙종 때 경신환국, 기사환국, 갑술환국이 옵니다.",
    "reviewedOn": "2026-10-14"
