    "hook": "서울의 조선 유적은 쓰임으로 가릅니다. 종묘는 왕과 왕비의 신주, 사직단은 땅과 곡식의 신, 성균관은 대성전과 명륜당, 경복궁은 조선 총독부 청사가 들어선 법궁, 창경궁은 창경원이 되었던 궁입니다.",
    "reviewedOn": "2026-10-14"
