    "hook": "조선의 중인은 하는 일로 가릅니다. 역관은 통역(사역원, 역과, 연행사 수행, 변승업), 의관은 의술, 향리는 수령 보좌, 서리는 중앙 관청의 실무입니다. 조선 후기 중인들은 시사를 만들어 시를 짓고 신분 상승 운동(철종 때 통청 운동)을 했습니다.",
