    "hook": "동학 농민 운동(고종 때, 1894년)은 고부 봉기(조병갑) → 안핵사 이용태의 탄압 → 1차 봉기(백산, 황토현, 황룡촌) → 전주성 점령 → 청군과 일본군 출병 → 전주 화약과 집강소 → 일본의 경복궁 점령과 청일 전쟁 → 2차 봉기(삼례) → 우금치 패배 → 시모노세키 조약(1895년)의 차례입니다.",
