    "hook": "일제 강점기 민족 문화 지키기는 한글과 역사로 나눕니다. 한글은 조선어 연구회(1921년)와 조선어 학회(1931년, 한글 맞춤법 통일안, 1942년 조선어 학회 사건)입니다. 역사는 박은식(혼), 신채호(낭가 사상, 조선상고사), 정인보(얼, 조선학 운동)입니다. 시일야방성대곡, 서유견문, 강화도 조약은 모두 그보다 앞입니다.",
