      "② 5년 단임 대통령을 직선으로 선출: 9차 개헌(전두환 정부 말, 1987년)입니다. 6월 민주 항쟁으로 대통령을 국민이 직접 뽑는 제도를 되찾았고, 지금 헌법이 이것입니다.",
      "③ 대통령이 국회의원의 3분의 1을 추천: 유신 헌법(박정희 정부, 1972년)입니다. 대통령이 추천한 의원들(유신 정우회)로 국회까지 손에 넣었습니다.",
