    "hook": "화폐는 나라와 왕으로 묶습니다. 건원중보(고려 성종 때, 첫 철전) → 은병, 해동통보(고려 숙종 때, 의천의 건의) → 조선통보(조선 세종 때) → 상평통보(인조 때 주조, 숙종 때 전국 유통) → 당백전(고종 때, 경복궁 중건) → 백동화(고종 때, 전환국) 순서입니다.",
    "reviewedOn": "2026-10-15"
